export function normalizeLineEndings(text) {
  let output = '';
  for (let index = 0; index < text.length; index += 1) {
    const char = text[index];
    if (char === '\r') {
      if (index + 1 < text.length && text[index + 1] === '\n') {
        index += 1;
      }
      output += '\n';
      continue;
    }
    output += char;
  }
  return output;
}

export function splitLines(text) {
  return text.split('\n');
}

export function isBlankLine(line) {
  for (let index = 0; index < line.length; index += 1) {
    const char = line[index];
    if (char !== ' ' && char !== '\t') {
      return false;
    }
  }
  return true;
}

export function trimStart(line) {
  let index = 0;
  while (index < line.length && (line[index] === ' ' || line[index] === '\t')) {
    index += 1;
  }
  return line.slice(index);
}

export function trimEnd(line) {
  let index = line.length;
  while (index > 0) {
    const char = line[index - 1];
    if (char !== ' ' && char !== '\t') {
      break;
    }
    index -= 1;
  }
  return line.slice(0, index);
}

export function trim(line) {
  return trimEnd(trimStart(line));
}

export function lowercase(text) {
  return text.toLowerCase();
}

export function isDigit(char) {
  return char >= '0' && char <= '9';
}

export function isAsciiLetter(char) {
  return (char >= 'a' && char <= 'z') || (char >= 'A' && char <= 'Z');
}

export function countLeadingSpaces(line, maxCount = line.length) {
  let count = 0;
  while (count < line.length && count < maxCount && line[count] === ' ') {
    count += 1;
  }
  return count;
}

export function endsWithSequence(text, sequence) {
  if (sequence.length > text.length) {
    return false;
  }
  return text.slice(text.length - sequence.length) === sequence;
}

export function containsLowercase(text, needle) {
  return lowercase(text).indexOf(needle) !== -1;
}

export function startsWithAt(text, start, fragment) {
  if (start + fragment.length > text.length) {
    return false;
  }
  return text.slice(start, start + fragment.length) === fragment;
}

