    } else if (char === ']') {
      depth -= 1;
      if (depth === 0) {
        return index;
      }
    }
    index += 1;
  }

  return -1;
}

function findMatchingParenthesis(text, start) {
  let depth = 1;
  let index = start + 1;

  while (index < text.length) {
    const char = text[index];
    if (char === '\n') {
      return -1;
