  const marker = text[start];
  if (marker !== '*' && marker !== '_') {
    return null;
  }

  const available = countRepeated(text, start, marker);
  const widths = [];
  if (available >= 3) {
    widths.push(3);
  }
  if (available >= 2) {
    widths.push(2);
  }
  widths.push(1);

  for (let optionIndex = 0; optionIndex < widths.length; optionIndex += 1) {
