import { parseCommandLine } from './cli/parse-args.mjs';
import { renderMarkdown } from './markdown/index.mjs';

export function buildOutputs(args) {
  const html1 = renderMarkdown(args.a);
  const html2 = renderMarkdown(args.b);
  const html3 = renderMarkdown(args.c);
  const html4 = renderMarkdown(args.d);
  const html5 = renderMarkdown(args.e);

  const section1 = renderMarkdown(`# Section 1\n${args.a}\n${args.b}`);
  const section2 = renderMarkdown(`# Section 2\n${args.c}\n${args.d}\n${args.e}`);
  const final = renderMarkdown(`${section1}\n\n${section2}`);

  return [html1, html2, html3, html4, html5, section1, section2, final];
}

export function run(argv, streams = { stdout: process.stdout, stderr: process.stderr }) {
  const parsed = parseCommandLine(argv);

  if (parsed.kind === 'help') {
    streams.stdout.write(parsed.text);
    return parsed.exitCode;
  }

  if (parsed.kind === 'error') {
    streams.stderr.write(parsed.text);
    return parsed.exitCode;
  }

  const outputs = buildOutputs(parsed.values);
  streams.stdout.write(`${outputs.join('\n')}\n`);
  return 0;
}

