import { buildHelpText, buildUsage, REQUIRED_OPTIONS } from './constants.mjs';

const LONG_OPTIONS = ['--help', '--a', '--b', '--c', '--d', '--e'];

function lastPathPart(value) {
  let lastSlash = -1;
  for (let index = 0; index < value.length; index += 1) {
    const char = value[index];
    if (char === '/' || char === '\\') {
      lastSlash = index;
    }
  }
  return lastSlash === -1 ? value : value.slice(lastSlash + 1);
}

function isDigit(char) {
  return char >= '0' && char <= '9';
}

function looksLikeNegativeNumber(token) {
  if (token.length < 2 || token[0] !== '-') {
    return false;
  }

  let index = 1;
  let sawDigit = false;
  let sawDot = false;

  if (token[index] === '.') {
    sawDot = true;
    index += 1;
  }

  while (index < token.length) {
    const char = token[index];
    if (isDigit(char)) {
      sawDigit = true;
      index += 1;
      continue;
    }
    if (char === '.' && !sawDot) {
      sawDot = true;
      index += 1;
      continue;
    }
    return false;
  }

  return sawDigit;
}

function tokenLooksLikeOption(token) {
  if (token === '') {
    return false;
  }
  if (token === '-h') {
    return true;
  }
  if (token.length >= 2 && token[0] === '-' && token[1] === '-') {
    return true;
  }
  if (token[0] === '-' && !looksLikeNegativeNumber(token)) {
    return true;
  }
  return false;
}

function resolveLongOption(namePart) {
  let match = null;
  let matchCount = 0;

  for (let index = 0; index < LONG_OPTIONS.length; index += 1) {
    const option = LONG_OPTIONS[index];
    if (option.slice(0, namePart.length) === namePart) {
      match = option;
      matchCount += 1;
    }
  }

  if (matchCount === 1) {
    return match;
  }

  return null;
}

function buildError(progName, message) {
  return {
    kind: 'error',
    exitCode: 2,
    text: `${buildUsage(progName)}\n${progName}: error: ${message}\n`,
  };
}

function resolveProgramName(argv) {
  if (argv.length > 1 && argv[1]) {
    return lastPathPart(argv[1]);
  }
  return 'test16.mjs';
}

export function parseCommandLine(argv) {
  const progName = resolveProgramName(argv);
  const values = { a: undefined, b: undefined, c: undefined, d: undefined, e: undefined };
  const extras = [];

  for (let index = 2; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h') {
      return { kind: 'help', exitCode: 0, text: buildHelpText(progName) };
    }

    if (token.length > 2 && token[0] === '-' && token[1] === 'h' && token[2] !== '-') {
      if (token[2] === '=') {
        return buildError(progName, `argument -h/--help: ignored explicit argument '${token.slice(3)}'`);
      }
      return { kind: 'help', exitCode: 0, text: buildHelpText(progName) };
    }

    if (token.length >= 2 && token[0] === '-' && token[1] === '-') {
      if (token === '--') {
        extras.push(token);
        continue;
      }

      let namePart = token;
      let attachedValue = null;
      let hasAttachedValue = false;
      let separatorIndex = -1;

      for (let scan = 2; scan < token.length; scan += 1) {
        if (token[scan] === '=') {
          separatorIndex = scan;
          break;
        }
      }

      if (separatorIndex !== -1) {
        namePart = token.slice(0, separatorIndex);
        attachedValue = token.slice(separatorIndex + 1);
        hasAttachedValue = true;
      }

      const resolved = resolveLongOption(namePart);
      if (resolved === '--help') {
        if (hasAttachedValue) {
          return buildError(progName, `argument -h/--help: ignored explicit argument '${attachedValue}'`);
        }
        return { kind: 'help', exitCode: 0, text: buildHelpText(progName) };
      }

      if (resolved === null) {
        extras.push(token);
        continue;
      }

      const key = resolved.slice(2);
      if (hasAttachedValue) {
        values[key] = attachedValue;
        continue;
      }

      const nextIndex = index + 1;
      if (nextIndex >= argv.length || tokenLooksLikeOption(argv[nextIndex])) {
        return buildError(progName, `argument ${resolved}: expected one argument`);
      }

      values[key] = argv[nextIndex];
      index += 1;
      continue;
    }

    extras.push(token);
  }

  const missing = [];
  for (let index = 0; index < REQUIRED_OPTIONS.length; index += 1) {
    const key = REQUIRED_OPTIONS[index];
    if (values[key] === undefined) {
      missing.push(`--${key}`);
    }
  }

  if (missing.length > 0) {
    return buildError(progName, `the following arguments are required: ${missing.join(', ')}`);
  }

  if (extras.length > 0) {
    return buildError(progName, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return { kind: 'ok', exitCode: 0, values };
}

